import { createSignal } from "solid-js";
import { createStore } from "solid-js/store";

export function getCivIconFromPolicy(card: TraditionDefinition): string {
	if (card.TraitType) {
		if (card.TraitType.includes("ATTRIBUTE")) {
			return "fonticon_attribute";
		} else {
			return card.TraitType.replace("TRAIT_", "civ_sym_").toLowerCase();
		}
	}
	return "fonticon_tradition";
}

//this is a 'secondary' icon and is placed immediately to the right of the civ or attribute icon
export function getAdditionalPolicyIcon(card: TraditionDefinition): string {
	const localPlayer: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	const localPlayerCulture: PlayerCulture = localPlayer!.Culture!;
	if (!card.TraditionType) {
		return "";
	}
	const policyIdeology = localPlayerCulture.getIdeologyForTradition(card.TraditionType);
	if (policyIdeology) {
		switch (policyIdeology) {
			case Database.makeHash("IDEOLOGY_COMMUNISM"): {
				return "govt_mini_comm";
			}
			case Database.makeHash("IDEOLOGY_DEMOCRACY"): {
				return "govt_mini_demo";
			}
			case Database.makeHash("IDEOLOGY_FASCISM"): {
				return "govt_idea_faci";
			}
			default:
				return "";
		}
	} else {
		return "";
	}
}

export function getCivBGFromPolicy(card: TraditionDefinition): string {
	if (card.TraitType) {
		return card.TraitType.replace("TRAIT_", "bg-panel-").toLowerCase();
	}
	return "";
}

//Make sure all  cards are the same height for slotting.
export const calculateGovtCardHeights = (root: HTMLElement) => {
	if (!root) {
		return;
	}

	const cards = Array.from(root.querySelectorAll<HTMLElement>(".policy-base-card"));
	if (cards.length === 0) {
		return;
	}

	//reset card height property so flexbox can take over so we can get a measurement
	cards.forEach((card) => (card.style.height = ""));
	waitForLayout(() => {
		const tallestCardHeight = Math.max(...cards.map((card) => card.offsetHeight));
		//set min height to force redraw
		setGovtCardHeight("110px");
		setGovtCardHeight(tallestCardHeight + "px");
	});
};

//these are used for visual card positioning as the user makes their choices
//chosen cards are put into the database when confirm button clicked
export const [activePolicyCards, setActivePolicyCards] = createStore<TraditionDefinition[]>([]);
export const [availablePolicyCards, setAvailablePolicyCards] = createStore<TraditionDefinition[]>([]);
export const [activeTraditionCards, setActiveTraditionCards] = createStore<TraditionDefinition[]>([]);
export const [availableTraditionCards, setAvailableTraditionCards] = createStore<TraditionDefinition[]>([]);
export const [activeCrisisCards, setActiveCrisisCards] = createStore<TraditionDefinition[]>([]);
export const [availableCrisisCards, setAvailableCrisisCards] = createStore<TraditionDefinition[]>([]);

//when you focus on an available policy or tradition, the corresponding slot is highlighted
export const [policiesFocus, setPolicySlotsFocused] = createSignal<boolean>(false);
export const [traditionsFocus, setTraditionSlotsFocused] = createSignal<boolean>(false);

//signal for setting card height to reuse on all tabs
export const [maxGovtCardHeight, setGovtCardHeight] = createSignal<string | undefined>(undefined);
